module.exports = {
 "Aggregate Instagram": "const profile = $('Apify Instagram').first()?.json ?? {};\nconst reelItems = $input.all().map(item => item.json ?? {});\nconst now = new Date().toISOString();\nconst hasProviderError = value => {\n  const messages = Array.isArray(value?.requestErrorMessages) ? value.requestErrorMessages : [];\n  const status = Number(value?.statusCode ?? value?.httpCode ?? 0);\n  return Boolean(value?.error || value?.errorDescription || value?.isRestrictedProfile === true || messages.length || (Number.isFinite(status) && status >= 400));\n};\nconst profileFailed = hasProviderError(profile);\nconst reelError = reelItems.find(hasProviderError);\nconst followersNumber = Number(profile.followersCount);\nconst reels = reelItems.filter(post => {\n  const rawId = String(post?.id ?? post?.shortCode ?? post?.url ?? '').trim();\n  return Boolean(rawId) && !hasProviderError(post);\n});\nconst reelsFailed = Boolean(reelError) && reels.length === 0;\nconst schemaInvalid = !profileFailed && !Number.isFinite(followersNumber);\nconst providerFailed = profileFailed || reelsFailed || schemaInvalid;\nlet errorClass = null;\nif (providerFailed) {\n  const combined = [profile, reelsFailed ? reelError : null].filter(Boolean);\n  const blocked = combined.some(value => (value.requestErrorMessages || []).some(message => String(message).toLowerCase().includes('blocked')));\n  const status = combined.map(value => Number(value.statusCode ?? value.httpCode ?? 0)).find(value => Number.isFinite(value) && value >= 400);\n  const errorCode = String((reelsFailed ? reelError : profile).error ?? '').toLowerCase();\n  if (combined.some(value => value?.isRestrictedProfile === true || String(value?.error ?? '').toLowerCase().includes('restricted profile'))) errorClass = 'apify_restricted_profile';\n  else if (errorCode === 'no_items') errorClass = 'apify_no_items';\n  else if (blocked) errorClass = 'apify_request_blocked';\n  else if (status) errorClass = 'apify_http_error';\n  else if (schemaInvalid) errorClass = 'apify_schema_invalid';\n  else errorClass = 'apify_provider_error';\n}\nconst finite = value => { const n = Number(value); return Number.isFinite(n) ? n : 0; };\nconst viewsOf = post => finite(post.videoPlayCount ?? post.playCount ?? post.videoViewCount ?? 0);\nif (providerFailed) return [{ json: {\n  ig_followers:null, ig_avg_likes:null, ig_avg_views:null, ig_total_post_views:null,\n  instagram_receipt:{expected:true,attempted:true,state:'provider_failed',item_count:0,fetched_at:now,source_date:null,used_last_good:false,error_class:errorClass}\n}}];\nconst avgLikes = reels.length ? Math.round(reels.reduce((sum, post) => sum + finite(post.likesCount), 0) / reels.length) : 0;\nconst avgViews = reels.length ? Math.round(reels.reduce((sum, post) => sum + viewsOf(post), 0) / reels.length) : 0;\nconst totalPostViews = reels.reduce((sum, post) => sum + viewsOf(post), 0);\nreturn [{ json: {\n  ig_followers:followersNumber, ig_avg_likes:avgLikes, ig_avg_views:avgViews, ig_total_post_views:totalPostViews,\n  instagram_receipt:{expected:true,attempted:true,state:reels.length?'success':'genuinely_empty',item_count:reels.length,fetched_at:now,source_date:now.slice(0,10),used_last_good:false,error_class:null}\n}}];",
 "Aggregate TikTok": "const rawItems = $input.all().map(item => item.json ?? {});\nconst now = new Date().toISOString();\nconst isErrorShaped = value => {\n  const statusCode = Number(value?.statusCode ?? value?.httpCode ?? 0);\n  return Boolean(\n    value?.error ||\n    value?.errorDescription ||\n    (Array.isArray(value?.requestErrorMessages) && value.requestErrorMessages.length) ||\n    (Number.isFinite(statusCode) && statusCode >= 400)\n  );\n};\nconst errorItem = rawItems.find(isErrorShaped);\nconst items = rawItems.filter(value => !isErrorShaped(value) && Object.keys(value).length > 0);\n\nlet errorClass = null;\nif (errorItem) {\n  const statusCode = Number(errorItem.statusCode ?? errorItem.httpCode ?? 0);\n  const blocked = (errorItem.requestErrorMessages ?? [])\n    .some(message => String(message).toLowerCase().includes('blocked'));\n  if (String(errorItem.error ?? '').toLowerCase() === 'no_items') errorClass = 'apify_no_items';\n  else if (blocked) errorClass = 'apify_request_blocked';\n  else if (Number.isFinite(statusCode) && statusCode >= 400) errorClass = 'apify_http_error';\n  else errorClass = 'apify_provider_error';\n}\n\nif (errorItem && items.length === 0) {\n  return [{\n    json: {\n      tiktok_followers: null,\n      tiktok_avg_plays: null,\n      tiktok_total_post_plays: null,\n      tiktok_receipt: {\n        expected: true,\n        attempted: true,\n        state: 'provider_failed',\n        item_count: 0,\n        fetched_at: now,\n        source_date: null,\n        used_last_good: false,\n        error_class: errorClass\n      }\n    }\n  }];\n}\n\nconst finite = value => {\n  const n = Number(value);\n  return Number.isFinite(n) ? n : 0;\n};\nconst first = items[0] ?? {};\nconst followers = finite(first.authorMeta?.fans ?? first.authorMeta?.followers ?? first.fans ?? 0);\nconst avgPlays = items.length\n  ? Math.round(items.reduce((sum, item) => sum + finite(item.playCount), 0) / items.length)\n  : 0;\nconst totalPostPlays = items.reduce((sum, item) => sum + finite(item.playCount), 0);\n\nreturn [{\n  json: {\n    tiktok_followers: followers,\n    tiktok_avg_plays: avgPlays,\n    tiktok_total_post_plays: totalPostPlays,\n    tiktok_receipt: {\n      expected: true,\n      attempted: true,\n      state: items.length ? 'success' : 'genuinely_empty',\n      item_count: items.length,\n      fetched_at: now,\n      source_date: now.slice(0, 10),\n      used_last_good: false,\n      error_class: null\n    }\n  }\n}];",
 "Merge Data3": "const client = $('Loop Over Items').item.json;\nconst ytData = $input.first()?.json ?? {};\nconst today = new Date().toISOString().slice(0, 10);\nconst now = new Date().toISOString();\nconst configured = value => {\n  const normalized = String(value ?? '').trim();\n  return Boolean(normalized && normalized.toUpperCase() !== 'N/A');\n};\n\nconst hasInstagram = configured(client.instagram_handle);\nlet igData = {};\nif (hasInstagram) {\n  try { igData = $('Aggregate Instagram').item.json ?? {}; } catch (error) {}\n} else {\n  try { igData = $('Instagram Not Configured').item.json ?? {}; } catch (error) {}\n}\n\nconst hasTikTok = configured(client.tiktok_handle);\nlet ttData = {};\nif (hasTikTok) {\n  try { ttData = $('Aggregate TikTok').item.json ?? {}; } catch (error) {}\n} else {\n  try { ttData = $('Empty TikTok').item.json ?? {}; } catch (error) {}\n}\n\nconst hasYouTube = configured(client.youtube_channel_id);\nconst normalizeReceipt = (candidate, defaults) => {\n  const hasCandidate = Boolean(candidate && typeof candidate === 'object');\n  const value = hasCandidate ? candidate : defaults;\n  return {\n    expected: Boolean(value.expected),\n    attempted: Boolean(value.attempted),\n    state: value.state,\n    item_count: Number(value.item_count ?? 0),\n    fetched_at: value.fetched_at ?? null,\n    source_date: value.source_date ?? null,\n    used_last_good: Boolean(value.used_last_good ?? false),\n    error_class: value.error_class ?? null\n  };\n};\n\nconst instagramReceipt = normalizeReceipt(igData.instagram_receipt, hasInstagram ? {\n  expected: true,\n  attempted: true,\n  state: 'provider_failed',\n  item_count: 0,\n  fetched_at: now,\n  source_date: null,\n  error_class: 'receipt_missing'\n} : {\n  expected: false,\n  attempted: false,\n  state: 'not_configured',\n  item_count: 0,\n  fetched_at: null,\n  source_date: null,\n  error_class: null\n});\nconst tiktokReceipt = normalizeReceipt(ttData.tiktok_receipt, hasTikTok ? {\n  expected: true,\n  attempted: true,\n  state: 'provider_failed',\n  item_count: 0,\n  fetched_at: now,\n  source_date: null,\n  error_class: 'receipt_missing'\n} : {\n  expected: false,\n  attempted: false,\n  state: 'not_configured',\n  item_count: 0,\n  fetched_at: null,\n  source_date: null,\n  error_class: null\n});\nconst youtubeReceipt = normalizeReceipt(ytData.youtube_receipt, hasYouTube ? {\n  expected: true,\n  attempted: true,\n  state: 'provider_failed',\n  item_count: 0,\n  fetched_at: now,\n  source_date: null,\n  error_class: 'receipt_missing'\n} : {\n  expected: false,\n  attempted: false,\n  state: 'not_configured',\n  item_count: 0,\n  fetched_at: null,\n  source_date: null,\n  error_class: null\n});\n\nreturn [{\n  json: {\n    date: today,\n    client_name: client.client_name,\n    client_key: client.__analytics_client_key,\n    row_number: client.row_number ?? null,\n    ig_followers: igData.ig_followers ?? null,\n    ig_avg_likes: igData.ig_avg_likes ?? null,\n    ig_avg_views: igData.ig_avg_views ?? null,\n    ig_total_post_views: igData.ig_total_post_views ?? null,\n    tiktok_followers: ttData.tiktok_followers ?? null,\n    tiktok_avg_plays: ttData.tiktok_avg_plays ?? null,\n    tiktok_total_post_plays: ttData.tiktok_total_post_plays ?? null,\n    yt_subscribers: ytData.yt_subscribers ?? null,\n    yt_total_views: ytData.yt_total_views ?? null,\n    yt_shorts_views: ytData.yt_shorts_views ?? '',\n    yt_longs_views: ytData.yt_longs_views ?? '',\n    analytics_receipt: {\n      schema: 'syncview.analytics.receipt.v1',\n      client_key: client.__analytics_client_key,\n      row_number: client.row_number ?? null,\n      client_name: client.client_name,\n      run_date: today,\n      terminal: false,\n      metrics_written: false,\n      result: 'processing',\n      platforms: {\n        instagram: instagramReceipt,\n        tiktok: tiktokReceipt,\n        youtube: youtubeReceipt\n      }\n    }\n  }\n}];",
 "Update Post Tracking": "const mergedData = $('Merge Data3').first().json;\nconst receipt = mergedData.analytics_receipt ?? { platforms: {} };\nconst clientName = mergedData.client_name;\nconst client = $('Loop Over Items').item.json;\nconst configured = value => { const normalized = String(value ?? '').trim(); return Boolean(normalized && normalized.toUpperCase() !== 'N/A'); };\nlet igPosts = [];\nif (['success', 'genuinely_empty'].includes(receipt.platforms?.instagram?.state)) {\n  try { igPosts = $('Fetch Instagram Reels').all().map(item => item.json ?? {}).filter(item => {\n    const rawId = String(item.id ?? item.shortCode ?? item.url ?? '').trim();\n    return Boolean(rawId) && !(item.error || item.errorDescription);\n  }); } catch (error) {}\n}\nlet ttPosts = [];\nif (configured(client.tiktok_handle) && ['success', 'genuinely_empty'].includes(receipt.platforms?.tiktok?.state)) {\n  try { ttPosts = $('Fetch TikTok Dataset').all().map(item => item.json ?? {}).filter(item => !(item.error || item.errorDescription)); } catch (error) {}\n}\nconst today = new Date().toISOString().slice(0, 10);\nconst rows = [];\nfor (const post of igPosts) {\n  const rawId = String(post.id ?? post.shortCode ?? post.url ?? '').trim();\n  if (!rawId) continue;\n  rows.push({post_id:'igr_'+rawId,client_name:clientName,platform:'instagram',first_seen_date:today,views_today:post.videoPlayCount ?? post.playCount ?? post.videoViewCount ?? 0,timestamp:post.taken_at ?? post.timestamp ?? post.date ?? '',post_tracking_action:'write'});\n}\nfor (const post of ttPosts) {\n  const rawId = String(post.id ?? post.webVideoUrl ?? post.videoUrl ?? post.shareUrl ?? '').trim();\n  if (!rawId) continue;\n  rows.push({post_id:'tt_'+rawId,client_name:clientName,platform:'tiktok',first_seen_date:today,views_today:post.playCount ?? 0,timestamp:post.createTime ? new Date(post.createTime * 1000).toISOString() : '',post_tracking_action:'write'});\n}\nif (rows.length) return rows.map(row => ({ json: row }));\nreturn [{json:{client_name:clientName,post_tracking_action:'skip',__skip_post_tracking:true}}];",
 "Compute Post Gains": "let newPosts = [];\ntry {\n  newPosts = $('Update Post Tracking').all()\n    .map(item => item.json ?? {})\n    .filter(item => !item.__skip_post_tracking && item.post_id);\n} catch (error) {}\n\nlet existingPosts = [];\ntry {\n  existingPosts = $('Read Post Tracking').all()\n    .map(item => item.json ?? {})\n    .filter(item => item.post_id);\n} catch (error) {}\n\nconst existingMap = {};\nfor (const post of existingPosts) {\n  existingMap[String(post.post_id).trim()] = post;\n}\n\nlet ig_views_gained_today = 0;\nlet tiktok_plays_gained_today = 0;\nconst updatedRows = newPosts.map(post => {\n  const existing = existingMap[String(post.post_id).trim()];\n  const viewsYesterday = existing ? Number(existing.views_today ?? 0) : 0;\n  const viewsToday = Number(post.views_today ?? 0);\n  const isFirstDay = !existing;\n  const publishedMs = Date.parse(post.timestamp || '');\n  const isBrandNew = Boolean(publishedMs && publishedMs >= Date.now() - 2 * 86400 * 1000);\n  const isReelsBaseline = post.platform === 'instagram' && String(post.post_id).startsWith('igr_') && isFirstDay;\n  // A post is only a daily-growth datapoint after it has been observed once by\n  // the Reels source. Its first Reels observation establishes that baseline.\n  const gained = isReelsBaseline\n    ? 0\n    : (isFirstDay ? (isBrandNew ? viewsToday : 0) : Math.max(0, viewsToday - viewsYesterday));\n\n  if (post.platform === 'instagram') ig_views_gained_today += gained;\n  if (post.platform === 'tiktok') tiktok_plays_gained_today += gained;\n\n  return {\n    post_id: String(post.post_id).trim(),\n    client_name: post.client_name,\n    platform: post.platform,\n    first_seen_date: existing ? existing.first_seen_date : post.first_seen_date,\n    views_yesterday: viewsYesterday,\n    views_today: viewsToday,\n    views_gained_today: gained\n  };\n});\n\nreturn [{\n  json: {\n    updatedRows,\n    ig_views_gained_today,\n    tiktok_plays_gained_today\n  }\n}];",
 "Compute Diffs": "let allRows = [];\ntry { allRows = $('Get Previous Rows').all().map(item => item.json ?? {}); } catch (error) {}\n\nconst mergedData = $('Restore Gains').first().json;\nconst output = { ...mergedData };\nconst receipt = JSON.parse(JSON.stringify(mergedData.analytics_receipt ?? {\n  schema: 'syncview.analytics.receipt.v1',\n  client_name: mergedData.client_name,\n  run_date: new Date().toISOString().slice(0, 10),\n  platforms: {}\n}));\nconst today = new Date().toISOString().slice(0, 10);\nconst previousRows = allRows\n  .filter(row => row.date && row.date < today)\n  .sort((a, b) => String(b.date).localeCompare(String(a.date)));\nconst previous = previousRows[0] ?? null;\nconst number = value => {\n  const parsed = Number(value);\n  return Number.isFinite(parsed) ? parsed : 0;\n};\nconst copyLastGood = (platform, fields) => {\n  const platformReceipt = receipt.platforms?.[platform];\n  if (platformReceipt?.state !== 'provider_failed') return false;\n  for (const field of fields) output[field] = previous ? previous[field] ?? null : null;\n  platformReceipt.used_last_good = Boolean(previous);\n  platformReceipt.source_date = previous?.date ?? null;\n  return true;\n};\n\nconst instagramFailed = copyLastGood('instagram', ['ig_followers', 'ig_avg_views', 'ig_avg_likes']);\nconst tiktokFailed = copyLastGood('tiktok', ['tiktok_followers', 'tiktok_avg_plays']);\nconst youtubeFailed = copyLastGood('youtube', ['yt_subscribers', 'yt_total_views', 'yt_shorts_views', 'yt_longs_views']);\n\nconst previousIgMonth = number(previous?.ig_views_this_month);\nconst previousTikTokMonth = number(previous?.tiktok_plays_this_month);\nconst previousYouTubeViews = number(previous?.yt_total_views);\n\noutput.ig_views_gained_today = instagramFailed ? 0 : number(mergedData.ig_views_gained_today);\noutput.tiktok_plays_gained_today = tiktokFailed ? 0 : number(mergedData.tiktok_plays_gained_today);\noutput.ig_views_this_month = instagramFailed\n  ? (previous ? previousIgMonth : null)\n  : previousIgMonth + output.ig_views_gained_today;\noutput.tiktok_plays_this_month = tiktokFailed\n  ? (previous ? previousTikTokMonth : null)\n  : previousTikTokMonth + output.tiktok_plays_gained_today;\noutput.yt_views_gained_today = youtubeFailed\n  ? 0\n  : Math.max(0, number(output.yt_total_views) - previousYouTubeViews);\n\nconst degraded = Object.values(receipt.platforms ?? {})\n  .some(platform => platform?.state === 'provider_failed');\nreceipt.terminal = true;\nreceipt.metrics_written = true;\nreceipt.result = degraded ? 'degraded' : 'success';\nreceipt.completed_at = new Date().toISOString();\noutput.analytics_receipt = receipt;\n\nreturn [{ json: output }];",
 "Classify & Sum": "const cutoffMs = Date.now() - 30 * 86400 * 1000;\nconst SHORT_MAX_SEC = 180;\nfunction durSec(iso) {\n  const m = String(iso || '').match(/PT(?:(\\d+)H)?(?:(\\d+)M)?(?:(\\d+)S)?/);\n  if (!m) return 0;\n  return (+(m[1] || 0)) * 3600 + (+(m[2] || 0)) * 60 + (+(m[3] || 0));\n}\nconst vids = ($input.first() && $input.first().json && $input.first().json.items) || [];\nlet shorts = 0, longs = 0;\nconst seen = new Set();\nfor (const v of vids) {\n  if (v.id && seen.has(v.id)) continue;\n  if (v.id) seen.add(v.id);\n  const pub = new Date((v.snippet && v.snippet.publishedAt) || 0).getTime();\n  if (Number.isNaN(pub) || pub < cutoffMs) continue;\n  const sec = durSec(v.contentDetails && v.contentDetails.duration);\n  const views = Number((v.statistics && v.statistics.viewCount) || 0);\n  if (sec > 0 && sec <= SHORT_MAX_SEC) shorts += views; else longs += views;\n}\nconst ef = $('Edit Fields').first().json;\nreturn [{ json: {\n  yt_subscribers: ef.yt_subscribers,\n  yt_total_views: ef.yt_total_views,\n  yt_shorts_views: shorts,\n  yt_longs_views: longs,\n  youtube_receipt: ef.youtube_receipt,\n} }];",
 "Restore Gains": "const ig_views_gained_today = Number($execution.customData.get('ig_views_gained_today') ?? 0);\nconst tiktok_plays_gained_today = Number($execution.customData.get('tiktok_plays_gained_today') ?? 0);\nconst mergedData = $('Merge Data3').first().json;\nreturn [{ json: { ...mergedData, ig_views_gained_today, tiktok_plays_gained_today } }];",
 "Split Post Rows": "const data = $input.first()?.json ?? {};\nconst igGain = Number(data.ig_views_gained_today ?? 0);\nconst tiktokGain = Number(data.tiktok_plays_gained_today ?? 0);\n$execution.customData.set('ig_views_gained_today', String(igGain));\n$execution.customData.set('tiktok_plays_gained_today', String(tiktokGain));\n\nconst rows = Array.isArray(data.updatedRows) ? data.updatedRows : [];\nif (!rows.length) {\n  return [{\n    json: {\n      client_name: $('Merge Data3').first().json.client_name,\n      post_tracking_action: 'skip',\n      __skip_post_tracking: true\n    }\n  }];\n}\nreturn rows.map(row => ({\n  json: {\n    ...row,\n    post_tracking_action: 'write',\n    __skip_post_tracking: false\n  }\n}));"
};
